List the available certificate authority contexts:
'''
$ step context list
▶ alpha-one
alpha-two
beta
'''`,
		Subcommands: cli.Commands{
			currentCommand(),
			listCommand(),
			removeCommand(),
			selectCommand(),
		},
	}

	command.Register(cmd)
}

